 5	export class SymbolResolver {
 6	  private astIndex: AstIndexClient;
 7	
 8	  constructor(astIndex: AstIndexClient) {
 9	    this.astIndex = astIndex;
10	  }
11	
12	  /**
13	   * Resolve a symbol (`name`, `Class.method`, `Class::method`) in one file.
14	   *
15	   * The file's structure is authoritative when it has symbols. Without one,
16	   * ast-index's symbol index is asked, but only a hit in that same file
17	   * counts, and its end line is read from the source — never guessed.
18	   */
19	  async resolve(
20	    qualifiedName: string,
21	    structure?: FileStructure,
22	    filePath?: string,
23	  ): Promise<ResolvedSymbol | null> {
24	    if (structure && structure.symbols.length > 0) {
25	      const found = this.pick(this.findAll(qualifiedName, structure));
26	      return found ? toResolved(found, structure.path) : null;
27	    }
28	
29	    const file = structure?.path ?? filePath;
30	    if (!file || splitName(qualifiedName).length > 1) return null; // can't check the class without a structure
31	
32	    const detail = await this.astIndex.symbol(qualifiedName);
33	    if (!detail || !this.pathMatches(detail.file, file)) return null;
34	
35	    const built = await buildFileStructure(file, [
36	      { name: detail.name, kind: detail.kind, start_line: detail.start_line, end_line: 0 },
37	    ]).catch(() => null);
38	    const sym = built && this.pick(
39	      findDeep(built.symbols, (s) => s.name === detail.name)
40	        .filter((s) => s.location.startLine <= detail.start_line && detail.start_line <= s.location.endLine),
41	    );
42	    return sym ? toResolved(sym, file) : null;
43	  }
44	
45	  /** Every symbol in the structure that `qualifiedName` names, in document order. */
46	  findAll(qualifiedName: string, structure?: FileStructure): SymbolInfo[] {
47	    if (!structure) return [];
48	    const parts = splitName(qualifiedName);
49	    const last = parts[parts.length - 1];
50	
51	    const byPath = parts.length === 1
52	      ? findDeep(structure.symbols, (s) => s.name === last)
53	      : findDeep(structure.symbols, (s) => s.name === parts[0])
54	        .flatMap((head) => this.descend(parts.slice(1), head.children));
55	    // Go methods are top-level with qualifiedName Receiver.Method
56	    const byQualified = findDeep(structure.symbols, (s) => s.qualifiedName === qualifiedName.replace(/::/g, '.'));
57	
58	    const seen = new Set<SymbolInfo>();
59	    return [...byPath, ...byQualified]
60	      .filter((s) => (seen.has(s) ? false : (seen.add(s), true)))
61	      .sort((a, b) => a.location.startLine - b.location.startLine);
62	  }
