153	    void sessionRegistries.flushAll();
154	    // Stop the 5-minute ast-index tick so we don't block exit on SIGINT/SIGTERM.
155	    // .unref() already makes it non-keeping, but clearing is defensive and
156	    // avoids a stray `update` firing during shutdown.
157	    astIndex.stopPeriodicUpdate();
158	  };

